UPDATE provider_institution SET
    intake_date = 'March, July, November',
    updated_at = NOW()
WHERE cricos_provider_code = '03763K';

UPDATE courses SET
    course_description = '<h4>Why Study This Course</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div>The Bachelor of Business at Adelaide Institute of Higher Education will ask you to consider the challenges of contemporary global business environments and encourage you to develop knowledge and skills to embrace cultural diversity and recognise it as an asset to business and the broader community.</div> <div><br/>Knowledge and skills in business management and operations will be developed to make a start in any business-related career and you will grow your awareness of theories and regulations that impact business practices and decision making.</div> <div> </div> <div>The Bachelor of Business provides a broad-based undergraduate business education that prepares you for a multitude of business contexts and roles. Students can also choose to incorporate a <strong>Hospitality Major </strong>or a<strong> Marketing Minor</strong> in their studies to improve their future opportunities in marketing and customer service related roles.</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><div><img alt="Business student at AIHE" src="/images/2023/12/08/bbus.jpg" title=""/></div></div></div></div></div></div></div></div></div></div><h4>Course Overview</h4><div><div><div><div><div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Duration</h3><div><p>3 years full-time study or 6 years part-time study.<br/><span><em>A full-time study load consists of 8 subjects per year.<br/> <br/></em></span><span><em>Students who wish to pursue a Hospitality Major can do so by completing eight approved hospitality elective subjects.<br/>Two Marketing subjects are already studied in the core, so students who choose to, can study two Marketing electives to complete a Marketing Minor.</em></span></p></div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Campus</h3><div>✓ Adelaide Campus<br/>✓ Melbourne Campus</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Applicants</h3><div><p>✓ Available for domestic students<br/>✓ Available for international students</p></div></div></div></div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Structure</h3><div>16 Core Subjects and 8 Elective Subjects</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Total Course Credit Points</h3><div>120</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Points per Subject</h3><div>5</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>AQF Level</h3><div>Level 7</div></div></div></div></div></div></div></div></div></div></div></div></div><h4>Subject Outline</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <p>The Bachelor of Business is offered in 3 Study Periods per year.<br/>Please click <strong><a href="https://www.aihe.sa.edu.au/course/bachelor-of-business-subject-descriptions/file">here</a></strong> for more detailed subject descriptions.</p> <p>To complete the degree, you must successfully pass 24 subjects, organised across three levels of increasing complexity. A full-time study load consists of 8 subjects per year. In Year 1 (Level 1), you will complete from those listed, 6 core subjects and 2 electives. In Year 2 (Level 2), the structure includes from those listed, 5 core subjects and 3 electives. Year 3 (Level 3) comprises from those listed, 4 core subjects, the capstone subject (WIL), and 3 elective subjects.</p> <p><br/>Students who wish to pursue a <strong>Hospitality Major</strong> can do so by completing 8 approved hospitality elective subjects.</p> <p>With 2 Marketing subjects already in the Core, students can choose 2 Marketing electives to form a <strong>Marketing Minor</strong>.<strong><br/></strong></p> </div></div></div></div></div><div><div><div><div><div><div><div aria-controls="sppb-ac-content-1702250822587-key-0" aria-expanded="true"><span aria-label="Core Subjects"><i aria-hidden="true"></i> </span><span aria-label="Core Subjects"> Core Subjects</span></div><div aria-labelledby="sppb-ac-heading-1702250822587-key-0"><div><div><div><div><div><ul> <li>ACC1001 Accounting for Managers</li> <li>BUS1001 Language in Business</li> <li>BUS1002 Perspectives in International Business</li> <li>BUS1003 Business Mathematics and Statistics</li> <li>ECO1001 Business Economics</li> <li>MKT1001 Marketing Fundamentals</li> <li>BUS2001 Careers and Networking</li> <li>BUS2002 Understanding Contemporary Organisations</li> <li>BUS2003 Managing Across Cultures</li> <li>FIN2001 Business Finance</li> <li>LAW2001 Australian Business Law</li> <li>BUS3001 Corporate Social and Environmental Responsibility</li> <li>BUS3002 Work Integrated Learning</li> <li>BUS3003 Business Research</li> <li>BUS3004 Business Models, Innovation and Entrepreneurship</li> <li>MKT3001 International Marketing</li> </ul></div></div></div></div></div></div></div><div><div aria-controls="sppb-ac-content-1702250822587-key-1" aria-expanded="false"><span aria-label="Elective Subjects"><i aria-hidden="true"></i> </span><span aria-label="Elective Subjects"> Elective Subjects</span></div><div aria-labelledby="sppb-ac-heading-1702250822587-key-1"><div><div><div><div><div><ul> <li>ACC2001 Management Accounting</li> <li>BUS1004 Business Operations</li> <li>BUS3006 International Study Tour</li> <li>BUS3007 Cultural Competence</li> <li>HRM1001 Human Resource Management</li> <li>ICT1001 Business Information Systems</li> <li>ICT2001 Business Analytics</li> <li>ICT3001 Building a Successful E-Business</li> <li>LAW3001 International Business Law</li> <li>MKT2001 Digital Marketing</li> <li>MKT2002 Consumer Behaviour</li> <li>PRJ2001 Project Management Concepts</li> <li>PRJ3001 Project Management in Practice</li> <li>HOS1001 Introduction to Hospitality and Tourism</li> <li>HOS1002 Hospitality Industry Structure and Management</li> <li>HOS2002 Service Management for Hospitality and Events</li> <li>HOS2003 Accommodation Service and Operations</li> <li>HOS2004 Sustainable Procurement for Hospitality and Tourism</li> <li>HOS3001 Hospitality Risk and Crisis Management</li> <li>HOS3002 Revenue and Yield Management</li> <li>HOS3003 Event Management</li> </ul></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div></div><h4>Learning Methodology</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <ul> <li>Seminars, lectures, group activities, case studies and practical support sessions.</li> <li>Includes, but is not limited to, group and individual assignments, exams and tests, role plays and participation, quizzes and presentations.</li> <li>Credit Transfer and Recognition of Prior Learning (RPL) available on application.</li> </ul> </div></div></div></div></div></div></div></div></div></div>',
    total_course_duration = '3 years',
    offshore_tuition_fee = 66150,  -- AUD total course fee (22,050/yr x 3 years)
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <p><strong>Academic Requirements (All students)<br/></strong></p> <ul> <li><span lang="en-AU">Satisfactory completion of Australian Year 12</span> or an international equivalent is required. International applicants should refer to the <strong><a href="/component/sppagebuilder/?view=page&amp;id=212" rel="noopener noreferrer" target="_blank">list of overseas qualifications</a></strong> accepted by AIHE for entry into the Bachelor of Business degree.</li> </ul> <p>Learn more about the ways you can meet this criteria by viewing our <strong><a href="/future-students/admissions-criteria">Admissions Criteria</a></strong>.<br/><br/><strong>English Language Requirements (Students with non-English native language)<br/></strong></p> <p>IELTS (Academic) 6.0 overall score with no band less than 5.5 or equivalent.<br/>Learn more about the ways you can meet this criteria by viewing our <strong><a href="/future-students/admissions-criteria">Admissions Criteria</a></strong>.<br/><br/><strong>Entry Pathways</strong></p> <div>AIHE accepts various post-graduate entry pathways for this course. Learn more about the various pathways by <strong><a href="https://www.aihe.sa.edu.au/contact">contacting us</a></strong>.</div> <div>Applicants can apply for credit transfer if eligible. For more information please check the <strong><a href="/future-students/credit-transfer-and-recognition-of-prior-learning">Course Credit/Recognition of Prior Learning</a></strong>.</div> </div></div></div></div></div></div></div></div></div></div>',
    apply_form = 'https://www.aihe.sa.edu.au/courses/bachelor-of-business',
    updated_at = NOW()
WHERE cricos_course_code = '0100123';
UPDATE courses SET
    course_description = '<h4>Why Study This Course</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div>The Master of Business Administration (MBA) at AIHE Adelaide, is designed for students who want to develop management and leadership knowledge and skills required for a business management career in diverse cultural environments. <br/><br/>The MBA addresses the global demand for high-quality business and management graduates with advanced cultural competence, lifelong learning and leadership skills.<br/><br/>Throughout the MBA, students are required to apply their knowledge and skills to practical problems and authentic scenarios that challenge their ability to fuse theory and practice.</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><div><img alt="Business student at AIHE" src="/images/2023/12/11/mba-header-2.png" title=""/></div></div></div></div></div></div></div></div></div></div><h4>Course Overview</h4><div><div><div><div><div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Duration</h3><div>2 years full-time study or 4 years part-time study.<br/><em>A full-time study load consists of 8 subjects per year.</em></div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Campus</h3><div>✓ Adelaide Campus<br/>✓ Melbourne Campus</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Applicants</h3><div><p>✓ Available for domestic students<br/>✓ Available for international students</p></div></div></div></div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Structure</h3><div>10 Core Subjects and 6 Elective Subjects</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Total Course Credit Points</h3><div>80</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Points per Subject</h3><div>5</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>AQF Level</h3><div>Level 9</div></div></div></div></div></div></div></div></div></div></div></div></div><h4>Subject Outline</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <p>With the AIHE MBA’s 10 core subject and 6 elective subject structure, students can choose between several study plan options.</p> <p>Students in our Program can structure their own broad-based MBA, having access to a wide variety of business and management related electives.</p> <p>Alternatively, students who wish to pursue a specific discipline or industry focus as part of their MBA program can devote their Capstone Project and electives to constructing a minimum four subject sequence in their choice of specialisation. After choosing a specialisation, students still have a choice of at least 3 more electives.</p> </div></div></div></div></div><div><div><div><div><div><div><div aria-controls="sppb-ac-content-1702946136569-key-0" aria-expanded="true"><span aria-label="Standard MBA"><i aria-hidden="true"></i> </span><span aria-label="Standard MBA"> Standard MBA</span></div><div aria-labelledby="sppb-ac-heading-1702946136569-key-0"><div><div><div><div><div><p><strong>10 Core, 6 Electives</strong></p> <div>The AIHE MBA provides students the opportunity to access a broad set of MBA study options. Students can study a program using the full range of electives on offer and can nominate a Capstone Project topic that relates to their choice of a wide variety of possible business issues and problems requiring solutions.</div> <div> </div> <div>This is useful for graduates wishing to gain work in organisations who require employees with a broad range of business and management skills and knowledge, and wish to gain a broad base of skills and knowledge to operate their own business.</div> <p><strong><br/>Core Subjects (10 Subjects)<br/></strong></p> <ul> <li>BUS9001 Strategic &amp; Critical Thinking in Business</li> <li>BUS9002 Managing People &amp; Organisations</li> <li>BUS9005 Economics for International Business</li> <li>BUS9004 Accounting &amp; Finance</li> <li>BUS9003 Strategic Planning for Innovation</li> <li>BUS9006 Entrepreneurship &amp; Innovation</li> <li>BUS9007 Strategic Marketing Management</li> <li>BUS9008 Research, Data Analysis &amp; Decision Making</li> <li>BUS9009 Corporate Governance &amp; Risk Management</li> <li>BUS9010 Capstone Project</li> </ul> <strong>Elective Subjects (Any 6, subject to prerequisites)</strong><br/> <ul> <li>BUS9020 Project Management for Innovation</li> <li>BUS9021 International Business and Corporate Social Responsibility</li> <li>BUS9022 Accounting &amp; Reporting for Management</li> <li>BUS9023 Corporate Finance</li> <li>BUS9024 Law for Leaders</li> <li>BUS9025 Communication in a Globalised Business Environment</li> <li>BUS9026 Strategic Human Resource Management</li> <li>BUS9030 Digital Marketing for Global Impact</li> <li>BUS9031 Sales Management</li> <li>BUS9032 Market Research</li> <li>BUS9040 Care Industry – Structure and Context</li> <li>BUS9041 Service Management in the Care Sector</li> <li>BUS9042 Issues in Aged and Disability Care Management</li> <li>BUS9050 Hospitality Industry Structure and Management</li> <li>BUS9051 Event Management</li> <li>BUS9052 Service Management for Hospitality and Events</li> <li>BUS9060 Digital Businesses for Strategic Advantage</li> <li>BUS9061 Cybersecurity</li> <li>BUS9062 IT Project Management</li> </ul> <em><br/>Please click <strong><a href="https://www.aihe.sa.edu.au/course/master-of-business-administration/subject-descriptions/file">here</a></strong> for a more detailed subject description.</em></div></div></div></div></div></div></div><div><div aria-controls="sppb-ac-content-1702946136569-key-1" aria-expanded="false"><span aria-label="Master of Business Administration (MBA) - Marketing Management Specialisation"><i aria-hidden="true"></i> </span><span aria-label="Master of Business Administration (MBA) - Marketing Management Specialisation"> Master of Business Administration (MBA) - Marketing Management Specialisation</span></div><div aria-labelledby="sppb-ac-heading-1702946136569-key-1"><div><div><div><div><div><p><strong>10 Core, 2 Marketing Management Electives, 4 Free Choice Electives</strong></p> <div>Through study of the Marketing Management specialisation as part of their AIHE MBA, students will learn how the Marketing function can assist management meet organisational goals and help graduates develop their leadership potential in or around this functional area. Such a study will equip students for graduate employment opportunities in organisations where Marketing is a key operational focus. Marketing subjects offered cover topics such as marketing strategy, digital marketing with global application, market research, and sales. Students will further research and apply their Marketing knowledge in the Capstone Project whose topic choice will further explore &amp;/or solve issues relating to the Marketing discipline.<br/><br/></div> <div>With a high proportion of students working part-time whilst studying, students working in sales consulting, market research, or other marketing-related roles will find these studies useful in expanding their understanding and skills in their current area of employment, with a view to their future graduate aspirations in the same or a different organisation in the industry.</div> <p><strong><br/>Core Subjects (10 Subjects)<br/></strong></p> <ul> <li>BUS9001 Strategic &amp; Critical Thinking in Business</li> <li>BUS9002 Managing People &amp; Organisations</li> <li>BUS9005 Economics for International Business</li> <li>BUS9004 Accounting &amp; Finance</li> <li>BUS9003 Strategic Planning for Innovation</li> <li>BUS9006 Entrepreneurship &amp; Innovation</li> <li>BUS9007 Strategic Marketing Management</li> <li>BUS9008 Research, Data Analysis &amp; Decision Making</li> <li>BUS9009 Corporate Governance &amp; Risk Management</li> <li>BUS9010 Capstone Project <br/>(To count as part of a Marketing Management specialisation, the approved individual project topic must be related to this area of endeavour)</li> </ul> <p><br/><strong>Marketing Management Electives (2 subjects)</strong></p> <ul> <li>BUS9030 Digital Marketing for Global Impact</li> <li>BUS9031 Sales Management</li> <li>BUS9032 Market Research<br/><em>(students who wish to study three subjects may do so by counting one as a free choice elective)</em></li> </ul> <p><strong>Free Choice Elective Subjects (4 subjects)<br/></strong><em>Any four from the full list of available electives, except for the electives already chosen for the specialisation (choices subject to prerequisites).</em><strong><br/></strong></p> <ul> <li>BUS9020 Project Management for Innovation</li> <li>BUS9021 International Business and Corporate Social Responsibility</li> <li>BUS9022 Accounting &amp; Reporting for Management</li> <li>BUS9023 Corporate Finance</li> <li>BUS9024 Law for Leaders</li> <li>BUS9025 Communication in a Globalised Business Environment</li> <li>BUS9026 Strategic Human Resource Management</li> <li>BUS9030 Digital Marketing for Global Impact</li> <li>BUS9040 Care Industry – Structure and Context</li> <li>BUS9041 Service Management in the Care Sector</li> <li>BUS9042 Issues in Aged and Disability Care Management</li> <li>BUS9050 Hospitality Industry Structure and Management</li> <li>BUS9051 Event Management</li> <li>BUS9052 Service Management for Hospitality and Events</li> <li>BUS9060 Digital Businesses for Strategic Advantage</li> <li>BUS9061 Cybersecurity</li> <li>BUS9062 IT Project Management</li> </ul> <p><br/><em>Please click <strong><a href="https://www.aihe.sa.edu.au/course/master-of-business-administration/subject-descriptions/file">here</a> </strong>for a more detailed subject description.</em></p></div></div></div></div></div></div></div><div><div aria-controls="sppb-ac-content-1702946136569-key-2" aria-expanded="false"><span aria-label="Master of Business Administration (MBA) - Care Management Specialisation"><i aria-hidden="true"></i> </span><span aria-label="Master of Business Administration (MBA) - Care Management Specialisation"> Master of Business Administration (MBA) - Care Management Specialisation</span></div><div aria-labelledby="sppb-ac-heading-1702946136569-key-2"><div><div><div><div><div><p><strong>10 Core, 3 Care Management Electives, 3 Free Choice Electives</strong></p> <div>Through the study of the Care Management specialisation as part of their AIHE MBA, students will gain an insight into the operation of, and issues facing, the Care sector. This will assist graduates to meet organisational and client service goals and help them to develop leadership potential in the sector. Such a study will improve graduate employment opportunities in firms where human care is a key operational focus. As well as studying the Care Management subjects offered, students will further research and apply their Care sector knowledge in the Capstone Project whose topic choice will further explore &amp;/or solve issues relating to the Care sector.<br/><br/></div> <div>With a high proportion of students working part-time whilst studying, students working in aged care, disability care, or other care-related roles will find these studies useful in expanding their understanding and skills in their current area of employment, with a view to their future aspirations in the same or a different organisation in the industry.</div> <p><strong><br/>Core Subjects (10 Subjects)<br/></strong></p> <ul> <li>BUS9001 Strategic &amp; Critical Thinking in Business</li> <li>BUS9002 Managing People &amp; Organisations</li> <li>BUS9005 Economics for International Business</li> <li>BUS9004 Accounting &amp; Finance</li> <li>BUS9003 Strategic Planning for Innovation</li> <li>BUS9006 Entrepreneurship &amp; Innovation</li> <li>BUS9007 Strategic Marketing Management</li> <li>BUS9008 Research, Data Analysis &amp; Decision Making</li> <li>BUS9009 Corporate Governance &amp; Risk Management</li> <li>BUS9010 Capstone Project <em>(To count as part of a Marketing Management specialisation, the approved individual project topic must be related to this area of endeavour)</em></li> </ul> <strong>Care Management Electives (3 subjects)</strong><br/> <ul> <li>BUS9040 Care Industry – Structure and Context</li> <li>BUS9041 Service Management in the Care Sector</li> <li>BUS9042 Issues in Aged and Disability Care Management</li> </ul> <br/><strong>Free Choice Elective Subjects (3 subjects)<br/></strong><em>Any three from the full list of available electives, except for the electives already chosen for the specialisation (choices subject to prerequisites).</em><br/> <ul> <li>BUS9020 Project Management for Innovation</li> <li>BUS9021 International Business and Corporate Social Responsibility</li> <li>BUS9022 Accounting &amp; Reporting for Management</li> <li>BUS9023 Corporate Finance</li> <li>BUS9024 Law for Leaders</li> <li>BUS9025 Communication in a Globalised Business Environment</li> <li>BUS9026 Strategic Human Resource Management</li> <li>BUS9030 Digital Marketing for Global Impact</li> <li>BUS9031 Sales Management</li> <li>BUS9032 Market Research</li> <li>BUS9050 Hospitality Industry Structure and Management</li> <li>BUS9051 Event Management</li> <li>BUS9052 Service Management for Hospitality and Events</li> <li>BUS9060 Digital Businesses for Strategic Advantage</li> <li>BUS9061 Cybersecurity</li> <li>BUS9062 IT Project Management</li> </ul> <p><br/><em>Please click <strong><a href="https://www.aihe.sa.edu.au/course/master-of-business-administration/subject-descriptions/file">here</a></strong> for a more detailed subject description.</em></p></div></div></div></div></div></div></div><div><div aria-controls="sppb-ac-content-1702946136569-key-3" aria-expanded="false"><span aria-label="Master of Business Administration (MBA) - Management Information Systems (MIS) Specialisation"><i aria-hidden="true"></i> </span><span aria-label="Master of Business Administration (MBA) - Management Information Systems (MIS) Specialisation"> Master of Business Administration (MBA) - Management Information Systems (MIS) Specialisation</span></div><div aria-labelledby="sppb-ac-heading-1702946136569-key-3"><div><div><div><div><div><p><strong>10 Core, 3 MIS Electives, 3 Free Choice Electives</strong></p> <div>Through the study of the MIS specialisation as part of their AIHE MBA, students will gain an appreciation of the role of information technology in the operations, communications, and security of businesses. This will assist graduates to enhance employment and leadership potential through their understanding of contemporary business systems in the setting and enacting of business strategy. As well as studying the MIS subjects offered, students will further research and apply their MIS knowledge in the Capstone Project whose topic choice will further explore &amp;/or solve issues relating to Management Information Systems.<br/><br/></div> <div>With a high proportion of students working part-time whilst studying, students working in IT-related roles, or who are IT hobbyists, will find these studies useful in expanding their current understanding and skills, with a view to their future aspirations in industry.</div> <p><strong>Core Subjects (10 Subjects)<br/></strong></p> <ul> <li>BUS9001 Strategic &amp; Critical Thinking in Business</li> <li>BUS9002 Managing People &amp; Organisations</li> <li>BUS9005 Economics for International Business</li> <li>BUS9004 Accounting &amp; Finance</li> <li>BUS9003 Strategic Planning for Innovation</li> <li>BUS9006 Entrepreneurship &amp; Innovation</li> <li>BUS9007 Strategic Marketing Management</li> <li>BUS9008 Research, Data Analysis &amp; Decision Making</li> <li>BUS9009 Corporate Governance &amp; Risk Management</li> <li>BUS9010 Capstone Project <em>(To count as part of a Marketing Management specialisation, the approved individual project topic must be related to this area of endeavour)</em></li> </ul> <strong>MIS Electives (3 subjects)</strong><br/> <ul> <li>BUS9060 Digital Businesses for Strategic Advantage</li> <li>BUS9061 Cybersecurity</li> <li>BUS9062 IT Project Management</li> </ul> <strong>Free Choice Elective Subjects (3 subjects)</strong><br/> <p><em>Any three from the full list of available electives, except for the electives already chosen for the specialisation (choices subject to prerequisites).</em></p> <ul> <li>BUS9020 Project Management for Innovation</li> <li>BUS9021 International Business and Corporate Social Responsibility</li> <li>BUS9022 Accounting &amp; Reporting for Management</li> <li>BUS9023 Corporate Finance</li> <li>BUS9024 Law for Leaders</li> <li>BUS9025 Communication in a Globalised Business Environment</li> <li>BUS9026 Strategic Human Resource Management</li> <li>BUS9030 Digital Marketing for Global Impact</li> <li>BUS9031 Sales Management</li> <li>BUS9032 Market Research</li> <li>BUS9040 Care Industry – Structure and Context</li> <li>BUS9041 Service Management in the Care Sector</li> <li>BUS9042 Issues in Aged and Disability Care Management</li> <li>BUS9050 Hospitality Industry Structure and Management</li> <li>BUS9051 Event Management</li> <li>BUS9052 Service Management for Hospitality and Events</li> </ul> <p><br/><em>Please click <strong><a href="https://www.aihe.sa.edu.au/course/master-of-business-administration/subject-descriptions/file">here</a></strong> for more detailed subject description.</em></p></div></div></div></div></div></div></div><div><div aria-controls="sppb-ac-content-1702946136569-key-4" aria-expanded="false"><span aria-label="Master of Business Administration (MBA) - Hospitality and Event Management Specialisation"><i aria-hidden="true"></i> </span><span aria-label="Master of Business Administration (MBA) - Hospitality and Event Management Specialisation"> Master of Business Administration (MBA) - Hospitality and Event Management Specialisation</span></div><div aria-labelledby="sppb-ac-heading-1702946136569-key-4"><div><div><div><div><div><p><strong>10 Core, 3 HEM Electives, 3 Free Choice Electives</strong></p> <div>Through the study of the Hospitality and Management specialisation as part of their AIHE MBA, students will gain an insight into the issues that underly operations in this industry. This will assist graduates to meet their organisational and client service goals and help to develop their leadership potential in the sector. Improved graduate employment opportunities in the sector will come through a clear focus on the industry’s needs and the opportunity to develop relevant contextual knowledge and skills as part of the MBA. As well as studying the specialist subjects offered, students will further research and apply their Hospitality and Events sector knowledge in the Capstone Project whose topic choice will further explore &amp;/or solve issues relating to the industry.<br/><br/></div> <div>With a high proportion of students working part-time whilst studying, students working in the broad range of hospitality and event-related roles will find these studies useful in expanding their understanding and skills in their current area of employment, with a view to their future aspirations in the same or a different organisation in the industry.<br/><br/></div> <p><strong>Core Subjects (10 Subjects)<br/></strong></p> <ul> <li>BUS9001 Strategic &amp; Critical Thinking in Business</li> <li>BUS9002 Managing People &amp; Organisations</li> <li>BUS9005 Economics for International Business</li> <li>BUS9004 Accounting &amp; Finance</li> <li>BUS9003 Strategic Planning for Innovation</li> <li>BUS9006 Entrepreneurship &amp; Innovation</li> <li>BUS9007 Strategic Marketing Management</li> <li>BUS9008 Research, Data Analysis &amp; Decision Making</li> <li>BUS9009 Corporate Governance &amp; Risk Management</li> <li>BUS9010 Capstone Project <em>(To count as part of a Marketing Management specialisation, the approved individual project topic must be related to this area of endeavour)</em></li> </ul> <br/><strong>Hospitality and Event Management Electives (3 subjects)</strong><br/> <ul> <li>BUS9050 Hospitality Industry Structure and Management</li> <li>BUS9051 Event Management</li> <li>BUS9052 Service Management for Hospitality and Events</li> </ul> <br/><strong>Free Choice Elective Subjects (3 subjects)<br/></strong><em>Any three from the full list of available electives, except for the electives already chosen for the specialisation (choices subject to prerequisites).</em><br/> <ul> <li>BUS9020 Project Management for Innovation</li> <li>BUS9021 International Business and Corporate Social Responsibility</li> <li>BUS9022 Accounting &amp; Reporting for Management</li> <li>BUS9023 Corporate Finance</li> <li>BUS9024 Law for Leaders</li> <li>BUS9025 Communication in a Globalised Business Environment</li> <li>BUS9026 Strategic Human Resource Management</li> <li>BUS9030 Digital Marketing for Global Impact</li> <li>BUS9031 Sales Management</li> <li>BUS9032 Market Research</li> <li>BUS9040 Care Industry – Structure and Context</li> <li>BUS9041 Service Management in the Care Sector</li> <li>BUS9042 Issues in Aged and Disability Care Management</li> <li>BUS9060 Digital Businesses for Strategic Advantage</li> <li>BUS9061 Cybersecurity</li> <li>BUS9062 IT Project Management</li> </ul> <p><br/><em>Please click <strong><a href="https://www.aihe.sa.edu.au/course/master-of-business-administration/subject-descriptions/file">here</a></strong> for a more detailed subject description.</em></p></div></div></div></div></div></div></div></div></div></div></div></div><div><div><div><h2> </h2><div><em>Please click <strong><a href="https://www.aihe.sa.edu.au/course/master-of-business-administration/subject-descriptions/file">here</a></strong> for a more detailed subject description.</em></div></div></div></div></div></div></div></div></div><h4>Learning Methodology</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <ul> <li>Seminars, lectures, group activities, case studies and practical support sessions.</li> <li>Includes, but is not limited to, group and individual assignments, exams and tests, role plays and participation, quizzes and presentations.</li> <li>Credit Transfer and Recognition of Prior Learning (RPL) available on application.</li> </ul> </div></div></div></div></div></div></div></div></div></div>',
    total_course_duration = '2 years',
    offshore_tuition_fee = 57750,  -- AUD total course fee (28,875/yr x 2 years)
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <p><strong>Academic Requirements (All students)<br/></strong></p> <div data-block-id="block-8d11bf54-814c-4b21-8854-8834196f7e34">An Australian Bachelor’s Degree or an international</div> <ul> <li>Qualification equivalent to AQF level 7</li> </ul> <p><strong>English Language Requirements (Students with non-English native language)<br/></strong></p> <p>IELTS (Academic) 6.5 overall score with no band less than 6.0 or equivalent.<br/>Learn more about the ways you can meet this criteria by viewing our <strong><a href="/future-students/admissions-criteria">Admissions Criteria</a></strong>.<br/><br/><strong>Entry Pathways</strong></p> <div>AIHE accepts various post-graduate entry pathways for this course. Learn more about the various pathways by <strong><a href="https://www.aihe.sa.edu.au/contact">contacting us</a></strong>.</div> <div>Applicants can apply for credit transfer if eligible. For more information please check the <strong><a href="/future-students/credit-transfer-and-recognition-of-prior-learning">Course Credit/Recognition of Prior Learning</a></strong>.</div> </div></div></div></div></div></div></div></div></div></div>',
