UPDATE courses SET
    course_description = '<h4>Why Study This Course</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <div data-block-id="block-6a484742-0c53-49ed-bfbc-8ba0a7cfaf4d">The Graduate Certificate in Management (GCM) provides students with the opportunity to develop advanced business knowledge and skills upon a core of strategic and critical thinking. It provides an opportunity for career-focused individuals to gain a formal business qualification that will prepare them for team leader and management roles.</div> <div data-block-id="block-15529217-cfd0-4953-b3c0-d5f19272df66"> </div> <div data-block-id="block-1a09986a-fff6-4e57-9a92-981c95ba24dd">As well as being a highly valued qualification in its own right, the GCM provides students with a foundation for further graduate-level studies in management and business. On completion of the GCM, students will have completed one quarter of the required study for the AIHE MBA, so will be well placed to continue their studies in that qualification or in a variety of other business-related Masters''s programs.</div> </div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><div><img alt="Business student at AIHE" src="/images/2023/12/11/course-header.png" title=""/></div></div></div></div></div></div></div></div></div></div><h4>Course Overview</h4><div><div><div><div><div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Duration</h3><div>6 months full-time study or 1-year part-time study.<br/><span><em>A full-time study load consists of 4 subjects per study period.</em></span></div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Campus</h3><div>✓ Adelaide Campus<br/>✓ Melbourne Campus</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Applicants</h3><div><p>✓ Available for domestic students<br/>✓ Available for international students</p></div></div></div></div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Structure</h3><div>1 Core Subject and 3 Elective Subjects</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Total Course Credit Points</h3><div>20</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>Points per Subject</h3><div>5</div></div></div></div></div></div></div></div><div><div><div><div><div><div><div><span><i></i></span></div></div><div><div><h3>AQF Level</h3><div>Level 8</div></div></div></div></div></div></div></div></div></div></div></div></div><h4>Subject Outline</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <p>Please click <strong><a href="https://www.aihe.sa.edu.au/course/graduate-certificate-in-management-subject-descriptions/file">here</a></strong> for more detailed subject descriptions.</p> </div></div></div></div></div><div><div><div><div><div><div><div aria-controls="sppb-ac-content-1702947241671-key-0" aria-expanded="true"><span aria-label="Core Subjects"><i aria-hidden="true"></i> </span><span aria-label="Core Subjects"> Core Subjects</span></div><div aria-labelledby="sppb-ac-heading-1702947241671-key-0"><div><div><div><div><div><ul> <li>BUS9001 Strategic &amp; Critical Thinking in Business</li> </ul></div></div></div></div></div></div></div><div><div aria-controls="sppb-ac-content-1702947241671-key-1" aria-expanded="false"><span aria-label="Elective Subjects"><i aria-hidden="true"></i> </span><span aria-label="Elective Subjects"> Elective Subjects</span></div><div aria-labelledby="sppb-ac-heading-1702947241671-key-1"><div><div><div><div><div><ul> <li data-block-id="block-6c2d2142-0371-408d-afbd-3b18f553e483">BUS9002 Managing People &amp; Organisations</li> <li data-block-id="block-878691bb-3c5a-4bc5-8d72-e977fccfde2e">BUS9004 Accounting &amp; Finance</li> <li data-block-id="block-8c48851b-ec2f-46f4-8745-ece06d92f16e">BUS9005 Economics for International Business</li> <li data-block-id="block-5a9e02b7-9812-4769-8d86-2a7a7f5a1610">BUS9006 Entrepreneurship &amp; Innovation</li> <li data-block-id="block-f2bf552c-246b-40dc-90bf-6218ec33f498">BUS9007 Strategic Marketing Management</li> <li data-block-id="block-43fa045d-923d-418d-9499-e35fc07012be">BUS9020 Project Management for Innovation</li> <li data-block-id="block-10ca1532-07f6-461e-ba4e-3646a827cc51">BUS9023 Corporate Finance</li> <li data-block-id="block-b00a73f8-c9cc-48a5-a386-6ee290088857">BUS9024 Law for Leaders</li> <li data-block-id="block-8f87fee5-b928-4bea-b3e7-e0567b62d3c8">BUS9026 Strategic Human Resource Management</li> </ul></div></div></div></div></div></div></div></div></div></div></div></div><div><div><div><h2> </h2><div><div> <p>For more information on subject descriptions please click <strong><a href="https://www.aihe.sa.edu.au/course/graduate-certificate-in-management-subject-descriptions/file" rel="noopener noreferrer" target="_blank">here</a></strong>.</p> </div></div></div></div></div></div></div></div></div></div><h4>Learning Methodology</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <ul> <li>Seminars, lectures, group activities, case studies and practical support sessions.</li> <li>Includes, but is not limited to, group and individual assignments, exams and tests, role plays and participation, quizzes and presentations.</li> <li>Credit Transfer and Recognition of Prior Learning (RPL) available on application.</li> </ul> </div></div></div></div></div></div></div></div></div></div>',
