    entry_requirements = '<h4>Entry Requirements</h4><div><div><div><div><div><div><div></div></div><div><div><div><h2> </h2><div><div> <p><strong>Academic Requirements (All students)</strong></p> <div data-block-id="block-8d11bf54-814c-4b21-8854-8834196f7e34">An Australian Bachelor’s Degree or an international</div> <ul> <li>Qualification equivalent to AQF level 7 or,</li> </ul> <div data-block-id="block-b07cda08-0ce3-4f1e-980b-bdd04e051f97">An Australian Advanced Diploma, Associate Degree, or an</div> <div data-block-id="block-69261307-0e99-4fc3-8a62-43bf575b2cb2">international qualification equivalent to AQF level 6, plus 2 years’ of</div> <ul> <li>Industry experience at supervisory level or,</li> </ul> <div data-block-id="block-2c6e0065-6f7c-4e5b-bfe6-f50ff47c6dcd">At least five years industry experience which</div> <ul> <li>Includes at least three years’ management/ supervisorial experience.</li> </ul> <div data-block-id="block-73c483a9-5ddb-4238-9563-667c4561b081">Learn more about the ways you can meet this criteria by viewing our <strong><a href="https://www.aihe.sa.edu.au/future-students/admissions-criteria" rel="noopener noreferrer" target="_blank">Admissions Criteria</a></strong>.</div> <p><br/><strong>English Language Requirements (Students with non-English native language)<br/></strong></p> <p>IELTS (Academic) 6.0 overall score with no band less than 6.0 or equivalent.<br/>Learn more about the ways you can meet this criteria by viewing our <strong><a href="/future-students/admissions-criteria">Admissions Criteria</a></strong>.<br/><br/><strong>Entry Pathways</strong></p> <div>AIHE accepts various post-graduate entry pathways for this course. Learn more about the various pathways by <strong><a href="https://www.aihe.sa.edu.au/contact">contacting us</a></strong>.</div> <div>Applicants can apply for credit transfer if eligible. For more information please check the <strong><a href="/future-students/credit-transfer-and-recognition-of-prior-learning">Course Credit/Recognition of Prior Learning</a></strong>.</div> </div></div></div></div></div></div></div></div></div></div>',
